import{_ as d,a0 as s,w as a,s as l,ao as p,I as n,x as o,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"安卓編年史 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/03 - The history of Android","title":"安卓編年史","tag":"The history of Android","desc":""},"relativePath":"The history of Android/03 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/03 - The history of Android.md"};function f(u,t,T,h,g,A){const e=s("Link");return a(),l("div",null,[t[20]||(t[20]=p('<h1 id="安卓編年史" tabindex="-1">安卓編年史 <a class="header-anchor" href="#安卓編年史" aria-label="Permalink to “安卓編年史”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/09hom2e.png" alt="從左到右：安卓0.9的主屏幕，添加的應用抽屜，以及快捷方式刪除界面。"></p><p><em>從左到右：安卓0.9的主屏幕，添加的應用抽屜，以及快捷方式刪除界面</em> [Ron Amadeo供圖]</p><h3 id="android-0-9-beta——嘿-這看起來很眼熟" tabindex="-1">Android 0.9, Beta——嘿，這看起來很眼熟！ <a class="header-anchor" href="#android-0-9-beta——嘿-這看起來很眼熟" aria-label="Permalink to “Android 0.9, Beta——嘿，這看起來很眼熟！”">​</a></h3>',4)),n("p",null,[t[1]||(t[1]=o("Milestone 5發佈後六個月，2008年8月， ",-1)),i(e,{href:"http://arstechnica.com/information-technology/2008/08/robotripping-hands-on-with-the-android-sdk-beta/"},{default:r(()=>[...t[0]||(t[0]=[o("安卓0.9發佈",-1)])]),_:1}),t[2]||(t[2]=o("。儘管安卓0.5 milestone版看起來“很早期”，而此時距離1.0發佈也只有兩個月時間了。因此，安卓0.9被打上了“beta”的標籤。在移動操作系統之路的另一邊，蘋果在一個月前已經發布了iPhone的第二代產品——iPhone 3G。第二代的iPhone搭載了第二代iPhone OS。蘋果同樣發佈了App Store應用商店並且已經開始接受應用提交。谷歌在追趕的道路上還有很多事情要做。",-1))]),t[21]||(t[21]=n("p",null,"谷歌拋棄了很多在Milestone 5中引入的UI設計。所有設計都回爐重造，採用全綵設計，白色方形圖標背景被拋棄。儘管0.9還是一個模擬器版本，相比與安卓發佈版來説看起來還是有點熟悉。安卓0.9有一個可用的桌面式主屏幕，一個特有的應用抽屜，多主屏，更多的應用程序，以及全功能（僅是它自身的）小部件。",-1)),t[22]||(t[22]=n("p",null,"Milestone 5中似乎沒有計劃支持安裝21個以上的應用，但在安卓0.9中有一個垂直滾動的應用抽屜，可以通過屏幕底部的灰色標籤打開。那時候，應用抽屜真的只是個抽屜。除了作為一個按鈕使用，灰色標籤還可以跟隨你的手指被向上拉起，就像通知面板被拉下來那樣。還額外添加了一些應用，像鬧鐘，計算器，圖片，信息，以及照相機。",-1)),t[23]||(t[23]=n("p",null,"這是第一個可以完全自定義主屏幕的版本。長按應用或小部件可以拖動它們。你可以把應用從抽屜中拖出到主屏幕快捷方式，或長按一個已經存在的主屏幕快捷方式來移動它。",-1)),n("p",null,[t[4]||(t[4]=o("安卓0.9提醒我們谷歌那時候並不像今天這樣擅長設計。實際上，當時安卓的部分設計工作外包給了其它公司。你可以從時鐘小插件看出一點端倪，它包含了“MALMO”字樣，它是設計公司",-1)),i(e,{href:"http://www.tat.se/"},{default:r(()=>[...t[3]||(t[3]=[o("The Astonishing Tribe",-1)])]),_:1}),t[5]||(t[5]=o("的所在地。",-1))]),t[24]||(t[24]=p('<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/widgets.png" alt="安卓0.9的“添加到主屏幕”對話框。"></p><p><em>安卓0.9的“添加到主屏幕”對話框</em> [Ron Amadeo供圖]</p><p>安卓0.9中只有三個小部件：時鐘，相框和搜索。搜索小部件在列表中甚至沒有一個自己的圖標——它用的是圖片的圖標。也許這裏面最有趣的選項是壁紙選項中的“購買的圖片”——一個“在非智能機時購買鈴聲是個普遍的現象”的遺留產物。谷歌要麼準備出售壁紙，要麼在某時已經加入了一個運營商。不過這家公司最終從未實現這個計劃。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/fcp.png" alt="小部件集合，打開的文件夾，重命名文件夾，以及一個複製/粘貼菜單。"></p><p><em>小部件集合，打開的文件夾，重命名文件夾，以及一個複製/粘貼菜單</em> [Ron Amadeo供圖]</p><p>在上面左側的截圖展示了谷歌搜索和圖片小部件。除了給你一個框進行輸入之外，搜索小部件做不了其它事情——它沒有自動補全或是附加的UI界面。在框裏輸入並點擊“Go”會啓動瀏覽器。底部的一排圖標顯示了一些菜單中通過長按得到的“快捷方式”，它會創建圖標並將應用啓動到特定屏幕。獨立的聯繫人，瀏覽器書籤，以及音樂播放列表都是0.9中可以被添加到主屏幕上的快捷方式。</p><p>“文件夾”是快捷方式標題下的一個選項，儘管它並不是任何東西的快捷方式。一旦創建了一個空文件夾，圖標就可以被移動進去並重新排列。不像今天，那時候的文件夾裏有什麼並不反映在文件夾圖標上，它一直是一個簡單的，白色的，看起來空空的文件夾圖標。</p><p>0.9同樣是第一個擁有系統級別複製/粘貼支持的安卓版本。長按任意文本框會喚出一個對話框，從而讓你保存或撤銷剪貼板中的文本。iOS直到近兩年後才支持複製/粘貼，所以在一段時間內，這是安卓的特色之一——以及許多網絡爭議的源頭。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/stuff.jpg" alt="從左到右：安卓0.9的新菜單，最近使用應用，電源選項，以及鎖屏。"></p><p><em>從左到右：安卓0.9的新菜單，最近使用應用，電源選項，以及鎖屏</em> [Ron Amadeo供圖]</p><p>安卓0.9真正地開始顯示出了它的成熟。主屏幕有完整的菜單選項，包括設置（儘管它還不能正常運作）以及搜索按鈕（谷歌肯定很喜歡你去搜索）。從那時起菜單的設計便已經最終成型，直到安卓2.3它轉變成了黑色。</p><p>長按實體Home鍵會喚出一個3x2方格的“最近使用應用”的菜單，這是一個一直持續到安卓3.0的設計。“最近使用應用”菜單會將背景顯示模糊化，但這個設計用在這裏顯得有些奇怪，在其它彈窗比如“添加到主屏幕”對話框或是主屏幕文件夾視圖之中並沒有用到該設計。電源菜單至少包含在了背景模糊設計組之中，它的圖標經過了重新設計，並且功能的對應名稱更改得更容易讓人接受。不過電源菜單圖標缺乏填充，顯得有些擁擠和不雅觀。</p><p>安卓0.9以其鎖屏為特色，雖然是非常基礎的樣子。黑色和灰色的鎖屏沒有任何屏幕解鎖的選項——你需要點擊實體菜單鍵。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',15)),n("p",null,[i(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:r(()=>[...t[6]||(t[6]=[o("Ron Amadeo",-1)])]),_:1}),t[7]||(t[7]=o(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1))]),n("p",null,[i(e,{href:"https://twitter.com/RonAmadeo"},{default:r(()=>[...t[8]||(t[8]=[o("@RonAmadeo",-1)])]),_:1})]),t[25]||(t[25]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),i(e,{href:"http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/3/"},{default:r(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/3/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=o("譯者：",-1)),i(e,{href:"https://github.com/alim0x"},{default:r(()=>[...t[11]||(t[11]=[o("alim0x",-1)])]),_:1}),t[14]||(t[14]=o(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[12]||(t[12]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=o("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:r(()=>[...t[16]||(t[16]=[o("Linux中國",-1)])]),_:1}),t[19]||(t[19]=o(" 榮譽推出",-1))])])}const w=d(m,[["render",f]]);export{b as __pageData,w as default};
